ALTER TYPE "Role" ADD VALUE IF NOT EXISTS 'BURSAR';
CREATE TABLE "StaffSalary" ("id" TEXT NOT NULL, "schoolId" TEXT NOT NULL, "userId" TEXT NOT NULL, "monthlyAmount" DECIMAL(65,30) NOT NULL DEFAULT 0, "latePenalty" DECIMAL(65,30) NOT NULL DEFAULT 0, "rewardAmount" DECIMAL(65,30) NOT NULL DEFAULT 0, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "StaffSalary_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "StaffSalary_userId_key" ON "StaffSalary"("userId"); CREATE INDEX "StaffSalary_schoolId_idx" ON "StaffSalary"("schoolId");
CREATE TABLE "PayrollEntry" ("id" TEXT NOT NULL, "schoolId" TEXT NOT NULL, "userId" TEXT NOT NULL, "month" TEXT NOT NULL, "baseSalary" DECIMAL(65,30) NOT NULL DEFAULT 0, "lateDays" INTEGER NOT NULL DEFAULT 0, "lateDeduction" DECIMAL(65,30) NOT NULL DEFAULT 0, "reward" DECIMAL(65,30) NOT NULL DEFAULT 0, "extraDeduction" DECIMAL(65,30) NOT NULL DEFAULT 0, "note" TEXT, "netPay" DECIMAL(65,30) NOT NULL DEFAULT 0, "status" TEXT NOT NULL DEFAULT 'DRAFT', "processedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "PayrollEntry_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "PayrollEntry_schoolId_userId_month_key" ON "PayrollEntry"("schoolId", "userId", "month"); CREATE INDEX "PayrollEntry_schoolId_month_idx" ON "PayrollEntry"("schoolId", "month");
ALTER TABLE "StaffSalary" ADD CONSTRAINT "StaffSalary_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "PayrollEntry" ADD CONSTRAINT "PayrollEntry_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
